                <div class="absolute left-[42%] top-[calc(50%+9px)] w-72 -translate-x-1/2 -translate-y-1/2 rounded-2xl border-b-4 border-[#d9262c] bg-[#e4ebf8] p-5 shadow-[0_18px_40px_rgba(15,25,60,.35)] lg:w-80 xl:w-96">
                    <img src="{{ asset('images/logo-transparent.png') }}" alt="Apex Claims Portal" class="h-auto w-full">
